import re
from typing import Dict, List, Any, Optional

# ------------------------------------------------------------------
# Helper functions (assumed to be available in the execution environment)
# ------------------------------------------------------------------
# node_by_title(doc, title) -> node dict or None
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child node dicts
# scope_nodes(doc, scope) -> list of nodes in the scope
# table_rows(node) -> iterator over (row_index, row_dict) from a table node
# ------------------------------------------------------------------


def _extract_entity_map(scope_node: Dict[str, Any]) -> Dict[str, str]:
    """Map from object ID string to its human‑readable description."""
    entity_map: Dict[str, str] = {}
    # Find the subnode that lists the objects
    for child in children(scope_node, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Objects"):
            for line in child.get("lines", []):
                m = re.match(r"Object (\d+): (.+)", line)
                if m:
                    obj_id, desc = m.group(1), m.group(2).strip()
                    entity_map[obj_id] = desc
    return entity_map


# ------------------------------------------------------------------
# Public API
# ------------------------------------------------------------------


def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all distinct entities in the given scope.
    Each entity is represented as {"id": str, "description": str}.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    entity_map = _extract_entity_map(scope_node)
    return [{"id": k, "description": v} for k, v in entity_map.items()]


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Return the last time point covered by the scope's records.
    Uses the Motion log table to find the maximum frame number.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None

    max_frame: Optional[int] = None
    for child in children(scope_node, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            for row_idx, row in table_rows(child):
                try:
                    f = int(row.get("frame", -1))
                except Exception:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all input records for the scope.
    Inputs are object entries into the scene and the state they arrive in.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Map object id to description
    entity_map = _extract_entity_map(scope_node)

    # Locate the Motion log table
    motion_node = None
    for child in children(scope_node, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            motion_node = child
            break

    # Collect first entries for each object in the motion log
    first_state: Dict[str, Dict[str, Any]] = {}
    first_row_idx: Dict[str, int] = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            obj_col = row.get("object", "")
            m = re.match(r"^(\d+)", obj_col)
            if not m:
                continue
            obj_id = m.group(1)
            if obj_id not in first_state:
                first_state[obj_id] = row
                first_row_idx[obj_id] = row_idx

    inputs_out: List[Dict[str, Any]] = []
    inp_counter = 0

    # Parse Events lines for object enters
    for child in children(scope_node, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            ev_lines = child.get("lines", [])
            for line_idx, line in enumerate(ev_lines):
                # Extract frame number
                frame_match = re.match(r"Frame (\d+):", line)
                if not frame_match:
                    continue
                frame_time = int(frame_match.group(1))

                # Detect object enter
                enter_match = re.search(
                    r"Object (\d+)\s+.*?(?:enters the scene|is in view when the video begins)",
                    line,
                )
                if not enter_match:
                    continue
                obj_id = enter_match.group(1)

                # Build fields from the first recorded state if available
                fields: Dict[str, Any] = {}
                src: List[Any] = [[child["node_id"], line_idx]]
                if obj_id in first_state:
                    state_row = first_state[obj_id]
                    # Convert numeric columns
                    try:
                        fields["x"] = float(state_row.get("x", 0.0))
                    except Exception:
                        fields["x"] = None
                    try:
                        fields["y"] = float(state_row.get("y", 0.0))
                    except Exception:
                        fields["y"] = None
                    try:
                        fields["vx"] = float(state_row.get("vx", 0.0))
                    except Exception:
                        fields["vx"] = None
                    try:
                        fields["vy"] = float(state_row.get("vy", 0.0))
                    except Exception:
                        fields["vy"] = None
                    try:
                        fields["speed"] = float(state_row.get("speed", 0.0))
                    except Exception:
                        fields["speed"] = None
                    # Append columns from this state
                    src.append(
                        [motion_node["node_id"], first_row_idx[obj_id], ["frame", "object", "x", "y", "vx", "vy", "speed"]]
                    )
                else:
                    # No motion data – still record the enter event
                    fields = {}

                inp_id = f"in-{inp_counter}"
                inp_counter += 1
                inputs_out.append(
                    {
                        "id": inp_id,
                        "time": float(frame_time),
                        "kind": "object-enter",
                        "entities": [obj_id],
                        "fields": fields,
                        "src": src,
                    }
                )

    return inputs_out


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all outcome records for the scope.
    Outcomes include object exits and collisions.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    out_list: List[Dict[str, Any]] = []
    out_counter = 0

    # Scan Events lines for exits and collisions
    for child in children(scope_node, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith(": Events"):
            ev_lines = child.get("lines", [])
            for line_idx, line in enumerate(ev_lines):
                # Extract frame
                frame_match = re.match(r"Frame (\d+):", line)
                if not frame_match:
                    continue
                frame_time = int(frame_match.group(1))

                # Exit event
                exit_match = re.search(r"Object (\d+).*?exits the scene", line)
                if exit_match:
                    obj_id = exit_match.group(1)
                    out_list.append(
                        {
                            "time": float(frame_time),
                            "kind": "object-exit",
                            "entities": [obj_id],
                            "value": None,
                            "src": [[child["node_id"], line_idx]],
                        }
                    )
                    out_counter += 1
                    continue

                # Collision event
                coll_match = re.search(r"Object (\d+).*?collides with.*?(?:Object )?(\d+)", line)
                if coll_match:
                    obj1 = coll_match.group(1)
                    obj2 = coll_match.group(2)
                    out_list.append(
                        {
                            "time": float(frame_time),
                            "kind": "collision",
                            "entities": [obj1, obj2],
                            "value": None,
                            "src": [[child["node_id"], line_idx]],
                        }
                    )
                    out_counter += 1

    return out_list


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """
    Return any constants defined in the scope.
    CLEVRER videos do not declare constants, so return an empty dict.
    """
    return {}
